import './cloud-sync.js';
import{DIVISION_TRACKS,DIVISION_CHAIN,DIVISION_DIAGNOSTIC,recommendDivisionTrack,divide,groupsModel,containersNeeded,correctChoiceIndex,pluralize,remainderContextLead,createBlankDivisionLearner}from'./division-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],storageKey='mathlab-division-v1',memory={};
function blankStore(){return{a:createBlankDivisionLearner(),b:createBlankDivisionLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankDivisionLearner(),hintLevel=0,attempts=0,sessionMissionId=null;
function ensureState(){const b=createBlankDivisionLearner();state={...b,...state,diagnostic:{...b.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...b.evidence,...state.evidence},family:{...b.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const plural=pluralize
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return DIVISION_TRACKS[state.track||'explorer']}function done(i){return Boolean(state.missions[DIVISION_CHAIN.missions[i].id]?.complete)}function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const x=state.sessions[id]||{attempts:0,hints:0};attempts=Number(x.attempts)||0;hintLevel=Number(x.hints)||0}function saveSession(){if(sessionMissionId){state.sessions[sessionMissionId]={attempts,hints:hintLevel};save()}}
function complete(i,dims=[],pending=false,preview=false){const m=DIVISION_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,attempts,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,attempts===0&&hintLevel===0&&!preview));if(pending)state.retestDue=Date.now()+20*60*60*1000;if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];attempts=0;hintLevel=0;sessionMissionId=null;save();setTimeout(render,400)}
function tryOnce(correct=false){if(!correct)attempts++;saveSession()}function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}function controls(){return'<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>'}
function choices(items,correct,position,attr){const tagged=items.map((x,i)=>({x,ok:i===correct})),right=tagged.find(x=>x.ok),ordered=tagged.filter(x=>!x.ok);ordered.splice(Math.max(0,Math.min(position,ordered.length)),0,right);return ordered.map(o=>`<button class="choice" data-${attr}="${o.ok?'correct':'wrong'}">${esc(o.x)}</button>`).join('')}
function groupModel(total,groups){const m=groupsModel(total,groups);return`<div class="division-model" aria-label="${groups} equal groups with ${m.each} in each group">${Array.from({length:groups},(_,i)=>`<span><b>${m.each}</b><small>group ${i+1}</small></span>`).join('')}</div><p class="equation">${total} ÷ ${groups} = ${m.each} &nbsp; because &nbsp; ${groups} × ${m.each} = ${total}</p>`}
function renderDiagnostic(){const d=state.diagnostic;if(d.index>=DIVISION_DIAGNOSTIC.length){state.track=state.track||recommendDivisionTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful numbers. It is not a grade label.</p><button class="primary" data-action="start">Build equal groups →</button></div>`;return}const q=DIVISION_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/3*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF 3</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map(x=>`<button class="choice" data-diag="${esc(x)}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Think about what one equal group means.</p>`;$$('[data-diag]').forEach(b=>b.onclick=()=>{const ok=b.dataset.diag===q.answer;d.answers.push({id:q.id,correct:ok});if(ok)d.score++;d.index++;feedback(ok?'Yes. The groups and total agree.':q.why,ok?'good':'try');save();setTimeout(()=>{feedback('');render()},500)})}
function renderBuild(){const t=track(),m=groupsModel(t.model.total,t.model.groups);$('#activity').innerHTML=`<p class="eyebrow">ONE STRUCTURE · THREE EQUATIONS</p><h3>${t.model.total} counters are shared equally among ${t.model.groups} groups.</h3>${groupModel(t.model.total,t.model.groups)}<p class="prompt">Which statement explains the model?</p><div class="answer-grid">${choices([`${t.model.groups} groups with ${m.each} in each group`,`${m.each} groups with ${t.model.total} in each group`,`${t.model.total-t.model.groups} counters are left over`],0,t.answerPosition,'build')}</div>${controls()}${hint(`Ask: ${t.model.groups} times what number makes ${t.model.total}?`)}`;$$('[data-build]').forEach(b=>b.onclick=()=>{tryOnce(b.dataset.build==='correct');if(b.dataset.build==='correct'){feedback('Exactly. Division and multiplication describe the same equal-group structure.','good');complete(1,['model','facts'])}else feedback('Match every number to its job: total, groups, and amount in each group.','try')})}
function renderRemainder(){const t=track(),d=divide(t.remainder.total,t.remainder.size);$('#activity').innerHTML=`<p class="eyebrow">COMPLETE GROUPS + LEFTOVERS</p><h3>Put ${t.remainder.total} objects into groups of ${t.remainder.size}.</h3><div class="remainder-board"><strong>${d.quotient}</strong><span>complete groups</span><b>${d.remainder}</b><span>left over</span></div><p class="prompt">Which equation proves it?</p><div class="answer-grid">${choices([`${t.remainder.size} × ${d.quotient} + ${d.remainder} = ${t.remainder.total}`,`${t.remainder.size} + ${d.quotient} + ${d.remainder} = ${t.remainder.total}`,`${t.remainder.size} × ${d.remainder} + ${d.quotient} = ${t.remainder.total}`],0,(t.answerPosition+1)%3,'remainder')}</div>${controls()}${hint('Multiply the size of each complete group by the number of complete groups. Then add the leftovers.')}`;$$('[data-remainder]').forEach(b=>b.onclick=()=>{tryOnce(b.dataset.remainder==='correct');if(b.dataset.remainder==='correct'){feedback(`Yes. ${d.quotient} complete groups use ${t.remainder.size*d.quotient}, and ${d.remainder} remain.`,'good');complete(2,['remainder','facts'])}else feedback('Check whether the multiplication counts all complete groups before the remainder is added.','try')})}
function decisionSelect(correct,answers){return `<select class="decision-select" data-decision="${correct}" aria-label="Choose what the remainder means"><option value="">Choose an answer</option>${answers.map(a=>`<option value="${a.value}">${esc(a.label)}</option>`).join('')}</select>`}
function renderContext(){const t=track(),ride=divide(t.context.total,t.context.size),need=containersNeeded(t.context.total,t.context.size),full=divide(t.remainder.total,t.remainder.size),report=divide(t.fresh.preview.total,t.fresh.preview.size);$('#activity').innerHTML=`<p class="eyebrow">THE STORY DECIDES</p><h3>The same remainder can lead to different answers.</h3><div class="decision-grid"><section><strong>1 · Everyone needs a place</strong><p>${remainderContextLead(t.context)}</p>${decisionSelect('up',[{value:'up',label:`${need} ${plural(t.context.container,need)} are needed`},{value:'ignore',label:`${ride.quotient} ${plural(t.context.container,ride.quotient)} are needed`},{value:'report',label:`${ride.quotient} full, ${ride.remainder} travelers left`}])}</section><section><strong>2 · Only full teams enter</strong><p>${t.remainder.total} players make teams of ${t.remainder.size}. Only complete teams can enter.</p>${decisionSelect('ignore',[{value:'ignore',label:`${full.quotient} complete teams enter`},{value:'up',label:`${full.quotient+1} teams enter`},{value:'report',label:`${full.quotient} teams and ${full.remainder} extra players enter`}])}</section><section><strong>3 · Report every item</strong><p>${t.fresh.preview.total} science samples are placed in trays of ${t.fresh.preview.size}. Record the exact result.</p>${decisionSelect('report',[{value:'report',label:`${report.quotient} full trays, ${report.remainder} ${plural('sample',report.remainder)} left`},{value:'ignore',label:`${report.quotient} trays`},{value:'up',label:`${report.quotient+1} trays with no remainder`}])}</section></div><button class="primary" data-action="check-decisions">Check all three decisions</button>${controls()}${hint('Ask what the story needs: room for everyone, only complete groups, or an exact report.') }`;const check=$('[data-action="check-decisions"]');check.onclick=()=>{const picks=$$('[data-decision]'),ok=picks.every(x=>x.value===x.dataset.decision);tryOnce(ok);if(ok){feedback('You used all three remainder decisions: round up, count complete groups, and report the leftover.','good');complete(3,['decision','remainder'],true)}else feedback('One story needs a different decision. Read what must happen to the leftover items.','try')}}
function freshStory(p,d,need){if(p.mode==='up')return{headline:`${p.total} ${p.item} travel in ${plural(p.container)} that hold ${p.size} each.`,question:`How many ${plural(p.container)} are needed?`,answers:[`${need} ${plural(p.container,need)}`,`${d.quotient} ${plural(p.container,d.quotient)}`,`${d.remainder} ${plural(p.container,d.remainder)}`],why:'Every item needs a place, so the remainder needs one more group.',wrong:'Ignoring the remainder would leave someone or something without a place.'};if(p.mode==='ignore')return{headline:`${p.total} ${p.item} are arranged in complete groups of ${p.size}. Extra items wait for the next round.`,question:'How many complete groups can be made?',answers:[`${d.quotient} complete ${plural('group',d.quotient)}`,`${need} complete ${plural('group',need)}`,`${d.remainder} complete ${plural('group',d.remainder)}`],why:'Only complete groups count, so the leftover items wait.',wrong:'Adding another group would count a group that is not complete.'};return{headline:`${p.total} ${p.item} are divided into groups of ${p.size}. Record the exact result.`,question:'Which answer reports both complete groups and leftovers?',answers:[`${d.quotient} groups, ${d.remainder} left`,`${need} groups, 0 left`,`${d.remainder} groups, ${d.quotient} left`],why:'An exact report keeps both the quotient and the remainder.',wrong:'The report must name both the complete groups and what remains.'}}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const h=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the method has faded from memory.</strong><p>About ${h} hours remain. Waiting checks what truly stayed.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses different numbers and does not count as delayed evidence.</p></div>`;return}const t=track(),p=ready?t.fresh.challenge:t.fresh.preview,d=divide(p.total,p.size),need=containersNeeded(p.total,p.size),story=freshStory(p,d,need),idx=correctChoiceIndex(p.total,p.size);const ordered=story.answers.map((x,i)=>({x,ok:i===0}));while(ordered.findIndex(x=>x.ok)!==idx)ordered.push(ordered.shift());$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW NUMBERS':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>${esc(story.headline)}</h3><p class="prompt">${esc(story.question)}</p><div class="answer-grid">${ordered.map(o=>`<button class="choice" data-fresh="${o.ok?'correct':'wrong'}">${esc(o.x)}</button>`).join('')}</div><div id="freshWhy" hidden><p class="prompt">Why?</p><div class="answer-grid"><button class="choice" data-why="correct">${esc(story.why)}</button><button class="choice" data-why="wrong">A remainder always means the same thing.</button></div></div>${controls()}${hint('Find the quotient and remainder. Then let the story decide what the answer must include.')}`;let accepted=false;$$('[data-fresh]').forEach(b=>b.onclick=()=>{const ok=b.dataset.fresh==='correct';tryOnce(ok);if(ok){accepted=true;$('#freshWhy').hidden=false;feedback('The number works. Now explain the remainder decision.','good')}else feedback(story.wrong,'try')});$$('[data-why]').forEach(b=>b.onclick=()=>{if(!accepted)return;const ok=b.dataset.why==='correct';tryOnce(ok);if(ok){feedback(ready?'You solved and explained a new remainder situation.':'Preview complete. Return later for fresh evidence.','good');complete(4,ready?['model','remainder','decision','transfer']:[],false,!ready)}else feedback('Read the story again. The remainder decision must match its goal.','try')})}
function renderComplete(i){const m=DIVISION_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=DIVISION_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i))return renderComplete(i);if(i===0)renderDiagnostic();else if(i===1)renderBuild();else if(i===2)renderRemainder();else if(i===3)renderContext();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=DIVISION_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');$$('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);attempts=0;hintLevel=0;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(DIVISION_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankDivisionLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const labels={model:'Equal-group model',facts:'Multiplication connection',remainder:'Remainder meaning',decision:'Context decision',transfer:'Fresh transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div><span>${v}</span><strong class="${state.evidence[k]}">${state.evidence[k]}</strong></div>`).join('');$('#evidenceTitle').textContent=`${learner==='a'?'Ella':'Mila'}’s learning evidence`}
function wire(){const action=e=>document.querySelector(`[data-action="${e}"]`);action('start')&&(action('start').onclick=()=>{complete(0)});action('next')&&(action('next').onclick=()=>{state.activeMission=Math.min(4,state.activeMission+1);save();render()});action('hint')&&(action('hint').onclick=()=>{hintLevel=Math.min(3,hintLevel+1);saveSession();renderMission()});action('preview')&&(action('preview').onclick=()=>{state.previewFresh=true;save();render()})}
function render(){ensureState();renderNav();renderTrack();renderEvidence();renderMission();wire();$('#helpNote').value=state.family.help||'';$('#explainNote').value=state.family.explain||'';$('#continueNote').value=state.family.continue||''}
$('#learnerSelect').value=learner;$('#learnerSelect').onchange=e=>{learner=e.target.value;store=readStore();store.learner=learner;state=store[learner]||createBlankDivisionLearner();sessionMissionId=null;save();render()};['helpNote','explainNote','continueNote'].forEach(id=>$('#'+id).onchange=e=>{state.family[id==='helpNote'?'help':id==='explainNote'?'explain':'continue']=e.target.value;save()});$('#resetPath').onclick=()=>{if(confirm('Reset this learner’s division path?')){state=createBlankDivisionLearner();sessionMissionId=null;save();render()}};render();